package com.roastingmonitor.controller;
import com.roastingmonitor.dto.*; import com.roastingmonitor.model.RoastingBatch; import com.roastingmonitor.service.RoastingService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/batches") public class BatchController {private final RoastingService s; public BatchController(RoastingService s){this.s=s;} @GetMapping public List<RoastingBatch> all(@RequestParam(required=false) String username,@RequestParam(defaultValue="false") boolean mine){return mine?s.myBatches(username):s.allBatches();} @PostMapping public RoastingBatch create(@Valid @RequestBody BatchRequest r,@RequestHeader("X-User") String u){return s.createBatch(r,u);} @PutMapping("/{id}") public RoastingBatch update(@PathVariable Long id,@Valid @RequestBody BatchRequest r,@RequestHeader("X-User") String u){return s.updateBatch(id,r,u);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.deleteBatch(id);} }
